import React, { useState } from 'react';
import Data from './FAQData';
import classes from './FAQ.module.scss';

function FAQ() {
  const [expandedIndex, setExpandedIndex] = useState(null);

  const toggleQuestion = (index) => {
    console.log("Before toggle - expandedIndex:", expandedIndex, "index:", index); // Debug

    // Если кликнули на уже открытый вопрос - закрываем его
    if (expandedIndex === index) {
      setExpandedIndex(null);
    } else {
      // Иначе - открываем новый вопрос
      setExpandedIndex(index);
    }

    console.log("After toggle - expandedIndex:", expandedIndex, "index:", index); // Debug
  };


  return (
    <div className={classes.faqContainer}>
      <div className={classes.titleBlock}>
        <img className={classes.wave} src="/img/wave.png" alt="wave.png" />
        <h1 className={classes.title}>FAQ</h1>
        <hr className={classes.hr} />
      </div>
      {Data.map((item, index) => (
        <div className={classes.faqItem} key={index}>
          <div className={classes.faqQuestion} onClick={() => toggleQuestion(index)}>
            <h2 className={classes.questionText}>{item.question}</h2>
            <span className={classes.toggleIcon}>{expandedIndex === index ? '-' : '+'}</span>
          </div>
          <div
            className={`${classes.faqAnswer} ${
              expandedIndex === index ? classes.expanded : ""
            }`}
          >
            {item.answer}
          </div>
        </div>
      ))}
    </div>
  );
}

export default FAQ;
